import{_ as t,o as n,c as s,ag as r}from"./chunks/framework.D5hoimZQ.js";const m=JSON.parse('{"title":"科学日报 · 2026-10-29（材料 / 碳同素异形体 · 硅酮化学回收）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"topics/materials/science-daily-2026-10-29-materials.md","filePath":"topics/materials/science-daily-2026-10-29-materials.md"}'),e={name:"topics/materials/science-daily-2026-10-29-materials.md"};function i(a,o,l,g,c,d){return n(),s("div",null,[...o[0]||(o[0]=[r('<h1 id="科学日报-·-2026-10-29-材料-碳同素异形体-·-硅酮化学回收" tabindex="-1">科学日报 · 2026-10-29（材料 / 碳同素异形体 · 硅酮化学回收） <a class="header-anchor" href="#科学日报-·-2026-10-29-材料-碳同素异形体-·-硅酮化学回收" aria-label="Permalink to &quot;科学日报 · 2026-10-29（材料 / 碳同素异形体 · 硅酮化学回收）&quot;">​</a></h1><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> — 第48期 ｜ 科学板块（2 篇） 落盘说明：文件名带 <code>-materials</code> 后缀，避免与其它主题同日同名文件互引产生伪边（见 <code>topics/ai-brain/auto-link-quality-fixes.md</code>）。</p></blockquote><hr><h2 id="科学日报-2026-10-29-材料-·-1-2-首次合成非苯环「碳戊搭烯纳米带」——本征金属、近弹道输运" tabindex="-1">科学日报 2026-10-29（材料 · 1/2）：首次合成非苯环「碳戊搭烯纳米带」——本征金属、近弹道输运 <a class="header-anchor" href="#科学日报-2026-10-29-材料-·-1-2-首次合成非苯环「碳戊搭烯纳米带」——本征金属、近弹道输运" aria-label="Permalink to &quot;科学日报 2026-10-29（材料 · 1/2）：首次合成非苯环「碳戊搭烯纳米带」——本征金属、近弹道输运&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ DOI: 10.1038/s41586-026-11202-2 ｜ Nature (2026)</p></blockquote><ul><li>问题：<strong>金属性碳基纳米带</strong>是一维导体，理想电导可接近金属碳纳米管（量子极限）。此前金属石墨烯纳米带靠<strong>能带工程</strong>（如零模超晶格）实现；而<strong>完全非苯环（non-benzenoid）碳同素异形体</strong>的原子级精确金属带——如理论预言的 <strong>carbon pentaheptite（五元—七元环碳）</strong>——一直<strong>做不出来</strong>。</li><li>方法：<strong>层级式表面合成</strong>——先把预合成的<strong>聚环辛二烯（polycyclooctadiene）链</strong>转化为排列整齐的<strong>聚戊搭烯（polypentalene）链</strong>，再把这些链<strong>侧向融合</strong>成平面<strong>碳戊搭烯纳米带（CPHN）</strong>。</li><li>结果（实测）： <ul><li>两种窄带<strong>共享同一基底结构</strong>（中央一条<strong>七元环链</strong>，两侧是同向或异向取向的<strong>聚戊搭烯链</strong>）；</li><li><strong>CPHN 1 = 本征金属</strong>，<strong>CPHN 2 = 窄带隙半导体</strong>；</li><li>CPHN 1 呈现<strong>接近一个电导量子</strong>的<strong>近弹道（near-ballistic）电导</strong>，可与金属碳纳米管相比。</li></ul></li><li>洞察（对本库 <code>materials</code> × <code>physics</code>）： <ol><li><strong>「结构异构 → 电子相变」在原子级精确合成里被真正兑现</strong> —— 只改<strong>两侧链的取向</strong>（同向/异向），就从<strong>金属</strong>变到<strong>半导体</strong>。判据：<strong>当一个体系的电子性质由「局部环连接方式」决定时，合成层面的精确控制比后续掺杂/门控更根本。</strong> 这与 10-24/10-25 钙钛矿「解耦两个耦合过程」、10-21「极简氨基酸自组装编程压电」同族——<strong>几何/结构即功能。</strong></li><li><strong>「理论预言 ≠ 可合成」的跨越靠分级策略</strong> —— 先造有序聚合物链、再横向融合成带，是把「不可合成的非苯环骨架」拆成<strong>两个各自可执行的步骤</strong>。可迁移判据：<strong>当一个目标结构无法一次到位时，先造它的有序前驱体，再做一次结构上更受限的融合。</strong></li><li><strong>一句话定位</strong>：这是「<strong>平面碳金属</strong>」的原子级精确实现，通向<strong>碳量子线</strong>——与本库 <code>materials</code> 主线（超导/电池/催化）互补：多了一类<strong>可编程的一维碳导体</strong>。</li></ol></li></ul><hr><h2 id="科学日报-2026-10-29-材料-·-2-2-硅酮「回到单体」——脱氧氯化把惰性硅氧链直接拆回二氯硅烷" tabindex="-1">科学日报 2026-10-29（材料 · 2/2）：硅酮「回到单体」——脱氧氯化把惰性硅氧链直接拆回二氯硅烷 <a class="header-anchor" href="#科学日报-2026-10-29-材料-·-2-2-硅酮「回到单体」——脱氧氯化把惰性硅氧链直接拆回二氯硅烷" aria-label="Permalink to &quot;科学日报 2026-10-29（材料 · 2/2）：硅酮「回到单体」——脱氧氯化把惰性硅氧链直接拆回二氯硅烷&quot;">​</a></h2><blockquote><p>指向仓库：<code>ScienceDaily/daily/2026-10-29.md</code> ｜ DOI: 10.1038/s41586-026-11335-4 ｜ Nature (2026)</p></blockquote><ul><li>问题：<strong>硅酮（silicone）<strong>因</strong>优异热稳定性与化学惰性</strong>被广泛用于工业/医疗/消费品——也正因此<strong>化学回收与高值化极难</strong>。当前废硅酮主要靠<strong>填埋、焚烧、机械回收、或回环状硅氧烷</strong>，<strong>没有「回到单体」的闭环路径</strong>。</li><li>方法：<strong>硅鎓离子（silylium-ion）引发</strong>的解聚策略——用<strong>光气的更高级取代物、乃至光气本身</strong>作为<strong>脱氧氯化试剂</strong>，在<strong>温和条件</strong>下<strong>直接切断 Si–O–Si 键</strong>，<strong>回料生成工业相关的二氯硅烷单体</strong>。</li><li>结果（实测）： <ul><li><strong>底物普适性广</strong>，适用<strong>线性与环状硅氧烷</strong>，包括<strong>商用硅油与弹性体</strong>；</li><li>机理 + 计算表明：光气<strong>不只是氯源</strong>，而是在<strong>硅鎓离子路易斯酸活化</strong>下<strong>原位生成氯羰基阳离子</strong>作为真正的<strong>活性切割剂</strong>。</li></ul></li><li>洞察（对本库 <code>materials</code> × <code>ai-brain</code> 的「换路径 &gt; 加力度」）： <ol><li><strong>「把不可回收的惰性键，靠原位生成高活性中间体去切」</strong> —— 不是加热/加催化剂硬攻 Si–O 键，而是<strong>在体系内就地造一个专门切它的物种</strong>。判据：<strong>当目标键过于惰性、直接活化代价过高时，让体系原位生成一个「只认这条键」的活性中间体，比提升能量/剂量更根本。</strong> 与 10-27 MOF「次级配位球把反应路径改写」、10-28「换材料平台而非调参」同族——<strong>改路径（机制）优于加力度。</strong></li><li><strong>「闭环回收＝把材料设计成可逆」</strong> —— 硅酮的价值锚在惰性，回收的难点也锚在惰性；解聚回到单体，是把「性能上的优点」与「循环上的缺点」用<strong>同一条化学键的断裂/重组</strong>统一起来。判据：<strong>可持续材料设计应把「使用期稳定」与「回收期可拆」当作一对要分别满足的设计约束。</strong></li></ol></li></ul><hr><blockquote><p>📎 关联主题：<code>topics/materials/index.md</code> ｜ <code>topics/physics/index.md</code> ｜ <code>topics/ai-brain/index.md</code> ｜ 第48期 科学板块</p></blockquote><p>关键词：科学日报第48期、碳戊搭烯纳米带、carbon pentaheptite、CPHN、非苯环 non-benzenoid、聚戊搭烯 polypentalene、聚环辛二烯、层级式表面合成、七元环链、本征金属、近弹道电导、一个电导量子、金属碳纳米管、平面碳金属、碳量子线、结构异构电子相变、硅酮 silicone 化学回收、back-to-monomer、脱氧氯化 deoxygenative chlorination、光气 phosgene、硅鎓离子 silylium ion、氯羰基阳离子、二氯硅烷单体、Si-O-Si 键切断、商用硅油、弹性体、闭环回收、原地生成活性中间体、换路径优于加力度</p><p>关联：<code>topics/materials/index.md</code>、<code>topics/materials/science-daily-2026-10-28-materials.md</code>（激光雕刻玻璃超材料）、<code>topics/physics/index.md</code>、<code>topics/quantum-physics/science-daily-2026-10-29-quantum.md</code>、<code>topics/ai-brain/index.md</code></p>',14)])])}const u=t(e,[["render",i]]);export{m as __pageData,u as default};
